"""Altcoin Season page: opens from Market's card (inside the app), hero + how it moved, a year chart with zones and a
crosshair, coins beating BTC (7/30/90 days), your coins vs BTC, the top 100 vs BTC (filters, search, show all), back."""
import sys, pathlib, json
from playwright.sync_api import sync_playwright
sys.path.insert(0, str(pathlib.Path(__file__).parent)); import e2e_setup as S
SH = pathlib.Path(__file__).parent / 'shots'; res = []
FIX = (pathlib.Path(__file__).parent / 'alt_fixture.json').read_text(); A = json.loads(FIX)
def check(n, c, d=''): res.append(bool(c)); print(('PASS ' if c else 'FAIL ') + n + ('' if c else f' -> {d}'), flush=True)
last = A['idx'][-1]; live = A['live'].get(str(A['today'])); NOW = live[0] if live else last[1]
with sync_playwright() as p:
    br = p.chromium.launch()
    for vn, vp in (('phone', dict(viewport={'width': 390, 'height': 844}, is_mobile=True, has_touch=True, device_scale_factor=2)), ('desktop', dict(viewport={'width': 1366, 'height': 900}, device_scale_factor=2))):
        for theme in ('light', 'dark'):
            ctx = br.new_context(**vp); S.setup(ctx); ctx.route('**/prices/m/alt.json', lambda r: r.fulfill(status=200, content_type='application/json', body=FIX))
            ctx.add_init_script(f"try{{localStorage.setItem('samsam_theme','{theme}');if(!sessionStorage.getItem('asT')){{localStorage.removeItem('samsam_as_view');localStorage.removeItem('samsam_mkt_altpage');sessionStorage.setItem('asT','1')}}}}catch(e){{}}")
            pg = ctx.new_page(); errs = []; pg.on('pageerror', lambda e: errs.append(str(e)))
            pg.goto(S.SITE + '/index.html'); pg.click('#samsamSignInBtn'); S.wait_ready(pg); pg.wait_for_timeout(800)
            pg.evaluate(f"document.documentElement.setAttribute('data-theme','{theme}')")
            pg.click('#cpBnav a[data-k=market]'); pg.wait_for_timeout(1500)
            mk = pg.frame(url=lambda u: 'market.html' in u); mk.wait_for_selector('#cardAlt'); mk.click('#cardAlt'); pg.wait_for_timeout(1800)
            fr = pg.frame(url=lambda u: 'altseason.html' in u)
            st = pg.evaluate("({h: location.hash, cur: document.querySelector('#cpBnav a[aria-current=page]')?.dataset.k})")
            check(f'{vn}/{theme}: Altcoin Season card opens the page inside the app; Market stays marked {st}', fr is not None and st['h'] == '#altseason' and st['cur'] == 'market', st)
            fr.wait_for_function("document.getElementById('asV').textContent.length > 3"); fr.evaluate(f"document.documentElement.setAttribute('data-theme','{theme}')")
            h = fr.evaluate("({v: asV.textContent, l: asL.textContent, cls: asL.className, stats: document.querySelectorAll('#asStats .as-stat').length, upd: asUpd.textContent})")
            want = 'Altcoin Season' if NOW >= 75 else 'Bitcoin Season' if NOW <= 25 else 'Leaning Altcoins' if NOW >= 50 else 'Leaning Bitcoin'
            check(f'{vn}/{theme}: hero = today\'s index {h}', h['v'].startswith(str(NOW)) and h['l'] == want and (('alt-side' in h['cls']) == (NOW >= 50)) and h['stats'] == 6 and h['upd'].startswith('Updated'), h)
            t = fr.evaluate("({tiles: [...document.querySelectorAll('.as-tile')].map(t=>t.dataset.k), open: [...document.querySelectorAll('.as-panel')].filter(p=>!p.hidden).length, hist: !!document.querySelector('#asT_hist svg') && asT_hist.innerText, br: asT_breadth.innerText, you: asT_you.innerText, top: asT_top.innerText, h: document.documentElement.scrollHeight})")
            check(f'{vn}/{theme}: four summary cards, nothing open at first, each with its summary {t}', t['tiles'] == ['hist', 'breadth', 'you', 'top'] and t['open'] == 0 and 'today' in t['hist'] and 'of 100' in t['br'] and 'beat BTC' in t['you'] and 'ahead of BTC' in t['top'], t)
            check(f'{vn}/{theme}: the page is short now ({t["h"]}px)', t['h'] < (1500 if vn == 'phone' else 1100), t['h'])
            pg.screenshot(path=str(SH / f'as_{vn}_{theme}_0.png'), full_page=False)
            fr.click('.as-tile[data-k=hist]'); fr.wait_for_timeout(500)
            o = fr.evaluate("({open: [...document.querySelectorAll('.as-panel')].filter(p=>!p.hidden).map(p=>p.dataset.k), exp: document.querySelector('.as-tile[data-k=hist]').getAttribute('aria-expanded'), top: Math.round(asP_hist.getBoundingClientRect().top)})")
            check(f'{vn}/{theme}: tapping History opens only its full view and scrolls to it {o}', o['open'] == ['hist'] and o['exp'] == 'true' and -2 <= o['top'] < 400, o)
            c = fr.evaluate("({svg: !!document.querySelector('#asChart svg'), lab: document.querySelector('#asChart svg')?.getAttribute('aria-label'), zones: [...document.querySelectorAll('#asChart .zl')].map(t=>t.textContent), paths: document.querySelectorAll('#asChart path').length})")
            check(f'{vn}/{theme}: a year chart with both zones and the ETH/BTC line {c}', c['svg'] and '365' in c['lab'] and c['zones'] == ['Altcoin Season', 'Bitcoin Season'] and c['paths'] >= 3, c)
            fr.click('#asRange button[data-r="90"]'); fr.wait_for_timeout(200)
            check(f'{vn}/{theme}: 90d range redraws', '90' in fr.get_attribute('#asChart svg', 'aria-label'))
            bb = fr.locator('#asChart svg').bounding_box(); fr.locator('#asChart svg').hover(position={'x': bb['width'] * .6, 'y': bb['height'] / 2}); fr.wait_for_timeout(150)
            tip = fr.evaluate("({on: getComputedStyle(asTip).display, t: asTip.innerText})")
            check(f'{vn}/{theme}: crosshair tooltip with date, index, BTC and ETH/BTC', tip['on'] == 'block' and 'BTC (90 days)' in tip['t'] and 'ETH / BTC' in tip['t'], tip)
            fr.check('#asOvDom'); fr.wait_for_timeout(150)
            check(f'{vn}/{theme}: BTC Dominance line can be added', fr.is_visible('#asOvDomL') and fr.evaluate("[...document.querySelectorAll('#asChart path')].some(p=>p.getAttribute('stroke')==='#f7931a')"))
            fr.locator('#asChart svg').hover(position={'x': bb['width'] * .3, 'y': bb['height'] / 2}); fr.wait_for_timeout(150)
            tt = fr.evaluate("asTip.innerText")
            check(f'{vn}/{theme}: older days show BTC Dominance marked as estimated, and the note says so', 'BTC Dominance' in tt and 'estimated' in tt and 'estimated from prices' in fr.inner_text('#asNote'), tt)
            fr.uncheck('#asOvDom')
            fr.check('#asOvUsdt'); fr.wait_for_timeout(150)
            fr.locator('#asChart svg').hover(position={'x': bb['width'] * .4, 'y': bb['height'] / 2}); fr.wait_for_timeout(150)
            ut = fr.evaluate("asTip.innerText")
            check(f'{vn}/{theme}: USDT Dominance line can be added (estimated on older days)', fr.evaluate("[...document.querySelectorAll('#asChart path')].some(p=>p.getAttribute('stroke')==='#ec4899')") and 'USDT Dominance' in ut and 'estimated' in ut, ut)
            fr.uncheck('#asOvUsdt')
            pg.screenshot(path=str(SH / f'as_{vn}_{theme}_h.png'))
            fr.click('.as-tile[data-k=breadth]'); fr.wait_for_timeout(400)
            check(f'{vn}/{theme}: opening another card closes History', fr.evaluate("[...document.querySelectorAll('.as-panel')].filter(p=>!p.hidden).map(p=>p.dataset.k)") == ['breadth'])
            b = fr.evaluate("({rows: document.querySelectorAll('#asBreadth .bar').length, tbl: document.querySelectorAll('#asTbl tbody tr').length, read: !asRead.hidden && asRead.innerText})")
            check(f'{vn}/{theme}: coins beating BTC over 7 / 30 / 90 days + a plain reading {b}', b['rows'] == 3 and b['tbl'] == 3 and b['read'], b)
            fr.click('.as-tile[data-k=you]'); fr.wait_for_timeout(400)
            y = fr.evaluate("({t: asYou.innerText.slice(0,200), rows: document.querySelectorAll('#asYou .as-row').length})")
            check(f'{vn}/{theme}: your coins vs BTC {y}', 'Your coins' in y['t'] and ('better' in y['t']) , y)
            fr.click('.as-tile[data-k=top]'); fr.wait_for_timeout(400)
            r = fr.evaluate("({n: document.querySelectorAll('#asRows .as-row').length, btc: document.querySelectorAll('#asRows .as-row.btc').length, more: !asMore.hidden})")
            check(f'{vn}/{theme}: top 100: first 25 + BTC as the yardstick, Show all {r}', r['n'] == 26 and r['btc'] == 1 and r['more'], r)
            fr.click('#asMore'); fr.wait_for_timeout(200)
            n = fr.evaluate("document.querySelectorAll('#asRows .as-row:not(.btc)').length")
            check(f'{vn}/{theme}: Show all → every coin ({n})', n == len([c for c in A['coins'] if c['p'][2] is not None]), n)
            fr.click('#asFilter button[data-f=beat]'); fr.wait_for_timeout(200)
            ok = fr.evaluate("[...document.querySelectorAll('#asRows .as-row:not(.btc) .vs b')].every(b=>b.className==='up')")
            check(f'{vn}/{theme}: Beating BTC shows only coins ahead of BTC', ok)
            fr.click('#asFilter button[data-f=all]'); fr.fill('#asSearch', 'eth'); fr.wait_for_timeout(200)
            s = fr.evaluate("[...document.querySelectorAll('#asRows .as-row')].map(r=>r.querySelector('.nm b').textContent)")
            check(f'{vn}/{theme}: search finds ETH {s[:4]}', any(x.startswith('ETH') for x in s) and len(s) < 20, s)
            fr.fill('#asSearch', '')
            ov = fr.evaluate("document.documentElement.scrollWidth <= innerWidth + 1")
            check(f'{vn}/{theme}: no sideways scrolling', ov)
            pg.screenshot(path=str(SH / f'as_{vn}_{theme}_3.png'))
            fr.click('.as-tile[data-k=top]'); fr.wait_for_timeout(300)
            check(f'{vn}/{theme}: tapping the open card again closes it', fr.evaluate("[...document.querySelectorAll('.as-panel')].filter(p=>!p.hidden).length") == 0)
            fr.click('.as-tile[data-k=you]'); fr.wait_for_timeout(300); fr.evaluate("location.reload()"); fr.wait_for_function("document.getElementById('asV').textContent.length > 3"); fr.wait_for_timeout(500)
            check(f'{vn}/{theme}: the last card you opened is open again next time', fr.evaluate("[...document.querySelectorAll('.as-panel')].filter(p=>!p.hidden).map(p=>p.dataset.k)") == ['you'])
            fr.click('#asBack'); pg.wait_for_timeout(600)
            check(f'{vn}/{theme}: Market Hub button returns to Market', pg.evaluate("location.hash") == '#market')
            check(f'{vn}/{theme}: no JS errors', not errs, errs[:3]); ctx.close()
    # opened on its own (not inside the app)
    ctx = br.new_context(viewport={'width': 390, 'height': 844}); S.setup(ctx); ctx.route('**/prices/m/alt.json', lambda r: r.fulfill(status=200, content_type='application/json', body=FIX))
    pg = ctx.new_page(); errs = []; pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.goto(S.SITE + '/index.html'); pg.click('#samsamSignInBtn'); S.wait_ready(pg)
    pg.goto(S.SITE + '/altseason.html'); pg.wait_for_function("document.getElementById('asV').textContent.length > 3"); pg.wait_for_timeout(500)
    check('standalone: has the bottom bar with Market marked', pg.evaluate("document.querySelector('#cpBnav a[aria-current=page]')?.dataset.k") == 'market')
    check('standalone: no JS errors', not errs, errs[:3]); ctx.close(); br.close()
print(f'{sum(res)}/{len(res)} passed'); sys.exit(0 if all(res) else 1)
